; Assembly symbol fixture for the kr232 adapter.
;
; Exercises what a hand-written .s file can declare: a .globl function that
; builds the ABI's ENTER frame chain (so the debugger can unwind its caller), a
; named data object with a .globl label (so it becomes a sized global), a
; frame-relative local declared with the documented .debug_var bridge
; directive, and one .debug_line-mapped instruction so the directive is covered
; as well as the assembler's physical-line default.
;
; Regenerated by tests/fixtures/kr232/regenerate.ps1 and checked by
; CheckFixtureDrift.cmake. Assertions live in tests/test_kr232_symbols.cpp and
; look lines up by token, never by number.

.globl asm_add
.globl asm_counter
.globl asm_table
.text
asm_add:
  enter #8, #0
  .debug_var asm_add asm_value -4 i32 4
  st [r13-4], r2
  ld r2, [r13-4]
  add r2, r3
  leave #0
  ret
.data
asm_counter:
  .word 7
asm_table:
  .word 11
  .word 22
  .word 33
.text
.globl _start
_start:
  enter #0, #0
  ld r2, #2
  ld r3, #3
  call asm_add
  ld r7, #0
  ld r2, #0
  sys
.globl asm_mapped
asm_mapped:
  ; The directive below claims this comment's line for the instruction after
  ; it, which is how a hand-written file can map code to a chosen source line.
  .debug_line 45
  ld r2, #1
  ret
